import pytest
from unittest.mock import MagicMock
from isort.deprecated.finders import KnownPatternFinder

class MockConfig:
    def __init__(self, sections, known_other):
        self.sections = sections
        self.known_other = known_other

    def __getattr__(self, name):
        # Allows dynamic creation of attributes that may not exist on the Config
        return getattr(self, name, [])

def test_known_patterns_initialization_with_sections():
    config = MockConfig(
        sections=["section1", "section2"],
        known_other={}
    )
    finder = KnownPatternFinder(config)

    assert len(finder.known_patterns) > 0

def test_known_patterns_initialization_with_known_other():
    config = MockConfig(
        sections=[],
        known_other={"section1": ["*.py"]}
    )
    finder = KnownPatternFinder(config)

    assert len(finder.known_patterns) > 0

def test_known_patterns_initialization_empty():
    config = MockConfig(
        sections=[],
        known_other={}
    )
    finder = KnownPatternFinder(config)

    assert len(finder.known_patterns) == 0

def test_known_patterns_initialization_with_mixed_patterns():
    config = MockConfig(
        sections=["section1"],
        known_other={"section1": ["*.py", "*.txt"]}
    )
    finder = KnownPatternFinder(config)

    assert len(finder.known_patterns) == 2
    assert finder.known_patterns[0][1] == "section1"
    assert finder.known_patterns[1][1] == "section1"

import pytest
from isort._vendored.tomli._re import match_to_datetime
from datetime import datetime, date, timezone, timedelta

def test_valid_date():
    match = create_mock_match('2023', '02', '28', None, None, None, None, False, None, None, None)
    assert match_to_datetime(match) == date(2023, 2, 28)

def test_valid_datetime():
    match = create_mock_match('2023', '02', '28', '13', '30', '00', '123456', False, None, None, None)
    assert match_to_datetime(match) == datetime(2023, 2, 28, 13, 30, 0, 123456)

def test_invalid_date():
    match = create_mock_match('2023', '13', '28', None, None, None, None, False, None, None, None)
    with pytest.raises(ValueError):
        match_to_datetime(match)

def test_invalid_datetime():
    match = create_mock_match('2023', '02', '28', None, None, 'xx', None, False, None, None, None)
    with pytest.raises(ValueError):
        match_to_datetime(match)

def test_zulu_time_datetime():
    match = create_mock_match('2023', '02', '28', '13', '30', '00', '123456', True, None, None, None)
    assert match_to_datetime(match) == datetime(2023, 2, 28, 13, 30, 0, 123456, tzinfo=timezone.utc)

def test_offset_datetime():
    match = create_mock_match('2023', '02', '28', '13', '30', '00', '123456', False, '+', '01', '00')
    expected_datetime = datetime(2023, 2, 28, 13, 30, 0, 123456, tzinfo=timezone(offset=timedelta(hours=1)))
    assert match_to_datetime(match) == expected_datetime

def test_negative_offset_datetime():
    match = create_mock_match('2023', '02', '28', '13', '30', '00', '123456', False, '-', '01', '00')
    expected_datetime = datetime(2023, 2, 28, 13, 30, 0, 123456, tzinfo=timezone(offset=timedelta(hours=-1)))
    assert match_to_datetime(match) == expected_datetime

def create_mock_match(*args):
    class MockMatch:
        def groups(self):
            return args
    return MockMatch()
